/* Target-only handoff storage preparation v1. Authenticated owner handlers only. */
async function prepareMemorySuiteHandoffTargetStorage(api, storage, owner, payload) {
  const readTarget = async () => {
    const character = await api.getCharacter();
    let index = Number(character?.chatPage || 0);
    if (typeof api.getCurrentChatIndex === 'function') index = Number(await api.getCurrentChatIndex());
    const chat = character?.chats?.[index];
    const marker = chat?.memorySessionBridge;
    const target = String(chat?.id || chat?.chatId || chat?.uuid || '');
    const policy = marker?.targetStoragePolicy;
    if (!target || target !== payload.targetChatId || marker?.targetChatId !== target
      || !payload.transferId || marker?.transferId !== payload.transferId
      || !marker.sourceChatId || marker.sourceChatId === target
      || (marker.targetStorageMode !== 'per_owner' && marker.targetStorageMode !== payload.mode)
      || !['plugin_only','server_only'].includes(payload.mode)
      || !policy?.participants?.some(p => p.owner === owner && p.mode === payload.mode)
      || marker.handoffJournal?.transferId !== payload.transferId
      || marker.handoffJournal?.state === 'completed') throw Error('HANDOFF_TARGET_STORAGE_IDENTITY_INVALID');
    return target;
  };
  const target = await readTarget();
  const before = await storage.getConnectionSettings({ force:true });
  const scope = before.scope;
  if (!scope?.scopeId || String(scope.chatId || scope.canonicalChatId || '') !== target) throw Error('HANDOFF_TARGET_STORAGE_SCOPE_MISMATCH');
  if (before.transition || before.migrationRequired) throw Error('HANDOFF_TARGET_STORAGE_TRANSITION_INCOMPLETE');
  if (before.recoveryRequired) throw Error('HANDOFF_TARGET_STORAGE_RECOVERY_REQUIRED');
  if (before.mode !== payload.mode) {
    // Only a new/local route may be prepared; never convert an unrelated server route.
    if (before.mode !== 'plugin_only') throw Error('HANDOFF_TARGET_STORAGE_MODE_CONFLICT');
    await readTarget();
    await storage.setScopeMode(scope, payload.mode);
  }
  await readTarget();
  const after = await storage.getConnectionSettings({ scope, force:true });
  if (after.mode !== payload.mode || after.scope?.scopeId !== scope.scopeId || after.recoveryRequired) throw Error('HANDOFF_TARGET_STORAGE_READBACK_FAILED');
  return { schema:'memory-suite.target-storage-preparation.v1', owner, targetChatId:target, transferId:payload.transferId, mode:after.mode, scope:after.scope, verified:true };
}
/* End target-only handoff storage preparation */
/* RisuAI native-branch target storage preparation v1. Verified Host Lineage only. */
async function prepareMemorySuiteNativeBranchTargetStorage(input = {}) {
  const storage = input?.storage;
  const owner = String(input?.owner || '').trim().toLowerCase();
  const lineage = input?.lineage && typeof input.lineage === 'object' ? input.lineage : null;
  const sourceScope = input?.sourceScope && typeof input.sourceScope === 'object' ? input.sourceScope : null;
  const targetScope = input?.targetScope && typeof input.targetScope === 'object' ? input.targetScope : null;
  const chatId = scope => String(scope?.chatId || scope?.canonicalChatId || '').trim();
  const characterId = scope => String(scope?.characterId || scope?.canonicalCharacterId || '').trim();
  if (!storage || !owner || !lineage || !sourceScope?.scopeId || !targetScope?.scopeId
    || lineage.schema !== 'librarian.host_lineage.v1' || lineage.kind !== 'native_branch'
    || lineage.status !== 'verified' || lineage.inheritanceEligible !== true
    || String(lineage.parentChatId || '') !== chatId(sourceScope)
    || String(lineage.hostChatId || '') !== chatId(targetScope)
    || sourceScope.scopeId === targetScope.scopeId
    || (characterId(sourceScope) && characterId(targetScope) && characterId(sourceScope) !== characterId(targetScope))) {
    const error = new Error('NATIVE_BRANCH_TARGET_STORAGE_IDENTITY_INVALID');
    error.code = 'NATIVE_BRANCH_TARGET_STORAGE_IDENTITY_INVALID';
    throw error;
  }
  if (typeof storage.getScopeMode !== 'function' || typeof storage.setScopeMode !== 'function'
    || typeof storage.createNativeBranchScopeCapability !== 'function' || typeof storage.openScopeView !== 'function') {
    const error = new Error('NATIVE_BRANCH_TARGET_STORAGE_SDK_UPGRADE_REQUIRED');
    error.code = 'NATIVE_BRANCH_TARGET_STORAGE_SDK_UPGRADE_REQUIRED';
    throw error;
  }
  const sourceState = await storage.getScopeMode(sourceScope);
  const targetBefore = await storage.getScopeMode(targetScope);
  if (sourceState?.scope?.scopeId && sourceState.scope.scopeId !== sourceScope.scopeId) throw new Error('NATIVE_BRANCH_SOURCE_SCOPE_READBACK_MISMATCH');
  if (targetBefore?.scope?.scopeId && targetBefore.scope.scopeId !== targetScope.scopeId) throw new Error('NATIVE_BRANCH_TARGET_SCOPE_READBACK_MISMATCH');
  const sourceMode = String(sourceState?.mode || 'plugin_only');
  // Validate every prerequisite without side effects, and issue the capability,
  // before changing the target mode or migrating data (design contract: an
  // invalid proof or non-durable source must not mutate the child).
  const capability = storage.createNativeBranchScopeCapability({ owner, lineage, sourceScope, targetScope });
  let sourceDurability = null;
  if (sourceMode !== 'plugin_only') {
    if (typeof storage.verifyNativeBranchSourceDurability === 'function') {
      sourceDurability = await storage.verifyNativeBranchSourceDurability({ scope:sourceScope, phase:'native_branch_source' });
    } else if (typeof storage.ensureHandoffReady === 'function') {
      sourceDurability = await storage.ensureHandoffReady({ scope:sourceScope, phase:'native_branch_source' });
    }
    if (sourceDurability?.verified !== true) {
      const error = new Error('NATIVE_BRANCH_SOURCE_STORAGE_NOT_DURABLE');
      error.code = 'NATIVE_BRANCH_SOURCE_STORAGE_NOT_DURABLE';
      throw error;
    }
  }
  let targetMode = String(targetBefore?.mode || 'plugin_only');
  let targetModeOrigin = targetBefore?.explicit === true ? 'explicit' : 'inherited';
  let migration = null;
  if (targetBefore?.explicit !== true && targetMode !== sourceMode) {
    const localInventory = typeof storage.inspectNativeBranchTargetLocalData === 'function'
      ? await storage.inspectNativeBranchTargetLocalData(targetScope)
      : { total:0, plugin:0, local:0, keys:[] };
    await storage.setScopeMode(targetScope, sourceMode, { origin:'inherited', source:'native_branch_inheritance' });
    targetMode = sourceMode;
    if (sourceMode !== 'plugin_only' && Number(localInventory?.total || 0) > 0) {
      targetModeOrigin = 'migrated';
      // Close the local -> server migration durably: the server copy must be
      // read back before the retained local bytes can be retired. A failed
      // readback leaves the local copy as the only (non-authoritative) remnant
      // and must not mark it retired.
      let retirement = null;
      let serverDigest = '';
      if (typeof storage.retireNativeBranchLocalTargetData === 'function') {
        try {
          retirement = await storage.retireNativeBranchLocalTargetData({
            scope:targetScope,
            keys:(Array.isArray(localInventory.keys) ? localInventory.keys : [])
              .filter(row => String(row?.space || 'plugin') === 'plugin')
              .map(row => String(row?.key || ''))
              .filter(Boolean)
          });
          serverDigest = String(retirement?.serverDigest || '');
        } catch (error) {
          const readbackError = new Error('NATIVE_BRANCH_STORAGE_MIGRATION_READBACK_FAILED');
          readbackError.code = 'NATIVE_BRANCH_STORAGE_MIGRATION_READBACK_FAILED';
          readbackError.cause = error;
          throw readbackError;
        }
      }
      migration = {
        schema:'memory-suite.native-branch-storage-migration.v1', migrated:true,
        fromMode:'plugin_only', toMode:sourceMode, retainedLocal:true,
        localItems:Number(localInventory.total || 0), pluginItems:Number(localInventory.plugin || 0),
        localStorageItems:Number(localInventory.local || 0), migratedAt:new Date().toISOString(),
        localDisposition:'retired_after_server_readback', serverDigest,
        retiredAt:String(retirement?.retiredAt || '')
      };
    }
  }
  const targetAfter = await storage.getScopeMode(targetScope);
  if (String(targetAfter?.mode || '') !== targetMode || targetAfter?.scope?.scopeId !== targetScope.scopeId) {
    const error = new Error('NATIVE_BRANCH_TARGET_STORAGE_MODE_READBACK_FAILED');
    error.code = 'NATIVE_BRANCH_TARGET_STORAGE_MODE_READBACK_FAILED';
    throw error;
  }
  if (targetAfter?.recoveryRequired) {
    const error = new Error('NATIVE_BRANCH_TARGET_STORAGE_RECOVERY_REQUIRED');
    error.code = 'NATIVE_BRANCH_TARGET_STORAGE_RECOVERY_REQUIRED';
    throw error;
  }
  const sourceView = storage.openScopeView(sourceScope, { capability, access:'read' });
  const targetView = storage.openScopeView(targetScope, { capability, access:'readwrite' });
  return {
    schema:'memory-suite.native-branch-storage-preparation.v1', owner,
    sourceScope:{ ...sourceScope }, targetScope:{ ...targetScope }, sourceMode,
    targetMode:String(targetAfter.mode || targetMode), targetModeOrigin,
    lineageDigest:String(lineage.prefixDigest || ''), verified:true, sourceDurability,
    capability, sourceView, targetView,
    receipt:{
      schema:'librarian.native_branch_storage_binding.v1',
      bindingId:`${owner}:${String(sourceScope.scopeKey || sourceScope.scopeId)}->${String(targetScope.scopeKey || targetScope.scopeId)}:${String(lineage.prefixDigest || '')}`, owner,
      sourceScopeKey:String(sourceScope.scopeKey || sourceScope.scopeId), targetScopeKey:String(targetScope.scopeKey || targetScope.scopeId),
      sourceMode, targetMode:String(targetAfter.mode || targetMode), targetModeOrigin,
      parentChatId:chatId(sourceScope), targetChatId:chatId(targetScope), lineageDigest:String(lineage.prefixDigest || ''),
      migration, status:'prepared', createdAt:new Date().toISOString(), committedAt:''
    }
  };
}
/* End RisuAI native-branch target storage preparation */

/* Manual-only candidate: explicit five-turn analysis; no ordinary request/output tracking. Server storage and existing Persona data are preserved. */
/* v0.26.66 / Pocket Studio: light responsive home, grouped bottom navigation, preserved persona and storage actions. */
/* v0.26.62 requires semantic Persona name/prompt readback and rejects explicit host write failures before committing Live Persona progress. */
/* Core-quality patch: Lore Reranker v2 replaces flat substring weighting with exact-anchor + rare-term BM25F-style scoring and splits protected lore into hard constraints (always retained) versus soft always/constant lore (budgeted inside Top-K). */
/* v0.26.61 removes repeated full-transcript hashing from committed-output capture, narrows source revalidation to the pending batch, caches stable negative/empty states, and skips Persona Proof/inheritance work for ordinary chats without a dynamic or Live Persona binding. */
/* v0.26.60 derives World Lore Compute routing from the current scope's Storage mode and combines Storage and Compute controls into one fail-open server panel. */
/* v0.26.59 adopts Storage SDK 1.8.13 paged key discovery, bounded batch reads, oversized-record fallback, and the 4 MiB interactive value guard. Persona DB, Live Persona, assets, provider calls, World Lore ranking, and RE:TRACE ownership are unchanged. */
/* v0.26.58 removes empty Live Persona indexes, readback-verifies shard deletion and Persona Proof writes, and rolls shard mutations back when the owner index cannot be durably committed. RE:TRACE now distinguishes shard-only content from proof/index-only metadata and only the latter can be cleaned after two stable scans plus authenticated Owner revalidation. */
/* v0.26.57 makes RE:TRACE discovery a storage-free fast path: capability and read-only inspection responses report the already-cached Storage status instead of waiting on durable scope-mode resolution. Persona ownership, provider calls, assets, Live Persona binding and storage-mode mutations are unchanged. */
/* v0.26.56 exposes the plugin-global Compute mode in the Server GUI through the shared Compute panel. The panel requires no user token or pairing key, keeps local as the zero-network fallback, and mounts independently from Storage connection diagnostics. */
/* v0.26.55 adopts the Librarian System product name and Storage SDK 1.8.11 / Compute SDK 0.3.2 labels without changing Persona ownership, provider calls, assets, local fallback, capture, or durable storage behavior. */
/* v0.26.54 makes prefer_server delegate the current World Lore rerank through a bounded interactive Compute call. LIA keeps the complete local reranker and remains authoritative; local is zero-network, shadow adopts local only, and timeout, server failure, or stale character/chat/persona/lore binding falls back locally. Compute bootstrap remains automatic and Storage-independent with no token or pairing input. */
/* v0.26.52 is a release-metadata synchronization update over v0.26.51. Live Persona, shared-store recovery, capture, provider, visual-asset, RE:TRACE peer protocol, Librarian System routing and persisted data contracts are unchanged. No Persona regeneration or data migration is required. */
/* v0.26.51 opts LIA-owned non-credential shared durable stores into Librarian System scope recovery. Result Vault, World Blueprint, legacy Live Persona, visual-asset catalog/presets and chunked asset backups now participate in mirror synchronization, server-to-pluginStorage restore, server tombstones, physical readback, transactional rollback and owner semantic validation. Provider secrets, illustration credentials/config, current-scope Live Persona semantics, capture and RE:TRACE contracts are unchanged. */
/* v0.26.50 assigns stable official UI ids to the main setting and hamburger button and prefers unregisterUIPart() during unload, with existing handle/legacy removal fallbacks retained for older/fork hosts. Live Persona, Persona Proof, provider, visual-asset, storage and capture behavior are unchanged. */
/* v0.26.49 uses the official api.onUnload lifecycle first (legacy/fork event fallback only), replaces deprecated startup api.log with console.log, and adds dispatch-health failover for hosts that register addRisuChatListener without ever firing it. The next narrative beforeRequest after a main afterRequest is a deterministic proof point: if no official output callback occurred, LIA removes the silent listener, promotes exactly one legacy backend, and immediately reconciles Live Persona from the original target chat. */
/* v0.26.48 adopts RisuAI 2026.8.240 committed-output capture for Live Persona Sync: the official output event supplies the exact chat/message slot, logical U+A revisions are upserted, five-turn LLM results are source-revalidated immediately before Persona mutation, and superseded Auto Continue/IGP/reroll work is discarded then requeued. Pre-2026.8.240 RisuAI and fork builds retain one mutually-exclusive legacy backend (script output, otherwise afterRequest live-chat reconcile). Persona Proof, Emotion Assets, ledger rollback, Librarian System storage, and RE:TRACE contracts remain unchanged. */
/* v0.26.47 adopts Storage SDK v1.8.10 transactional mode preflight and authoritative mirror tombstone handling while retaining scoped index, binding digest and strict JSON restore validation. */
/* v0.26.45 adopts Storage SDK v1.8.8: the active plugin-only scope is a strict zero-network boundary even when other scopes use the server, shared and foreign-scope keys stay local, and applying plugin-only does not reconnect. */
/* v0.26.44 adopts Storage SDK v1.8.7: server-to-pluginStorage restore requires verified candidate coverage and readback, failed recovery remains server-only under a durable recovery guard, and terminal work results stay visible. */
/* v0.26.43 adopts Storage SDK v1.8.6: timed-out server requests are aborted, failed data routes open the shared offline circuit, background resources are disposed on unload, and hot-reload globals are released safely. */
/* v0.26.42 pre-resolves global/shared/explicit-scope storage keys, bounds current-character/chat host calls so owner inspection cannot hang indefinitely, and keeps current-scope-only bindings on the verified scope path. */
/* v0.26.39 removes idle bridge polling that could flood PocketRisu/WebView message handlers: Live Persona Sync is output-driven with a cached enabled-binding fast gate, Persona Proof badge refresh is event-driven and diff-only, afterRequest proof exits before chat/context reads when no proof request is pending, and a singleton runtime fence disposes stale plugin instances after hot reload. Live Persona analysis cadence, Librarian System keys/schemas, RE:TRACE handoff, Persona generation, and provider behavior are unchanged. */
/* v0.26.37 upgrades Live Persona delta-ledger turn identity to a backward-compatible stable-message scheme: new ledgers prefer msg.chatId/other RisuAI IDs plus content digests, while existing index+text fingerprints remain valid under the legacy schema. Scope/storage keys are unchanged. */
