      startedAt: now, updatedAt: now, lastActivityAt: now, finishedAt: 0,
      totalItems: 0, processedItems: 0, processedBytes: 0, transferredBytes: 0,
      uploaded: 0, restored: 0, matched: 0, removedByTombstone: 0,
