    app.querySelectorAll("#dlg-cand [data-detail-root]").forEach(root=>{root.innerHTML='<div class="empty"><b>실제 후보 결과가 없습니다.</b><span>후보 생성 작업을 완료한 뒤 표시합니다.</span></div>';});
